from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction
from typing import Iterable

from flint import acb, arb, ctx, fmpq, fmpz, fmpz_mat, fmpz_poly

from ._numeric import (
    InputMode,
    arb_log2_positive,
    as_acb_and_mode,
    binary_magnitude_exponent,
    choose_scale_bits,
    round_arb_midpoint_to_int,
    usable_accuracy_bits,
    working_precision_bits,
)
from .models import (
    AlgRecognizeResult,
    InsufficientAccuracyError,
    NoRelationFound,
    SearchLimitError,
)
from ._typing import NumericInput


@dataclass(frozen=True)
class _Candidate:
    polynomial: fmpz_poly
    residual: acb
    score_bits: arb
    height: int
    degree: int
    lattice_vector: tuple[int, ...]
    scale_bits: int


def _primitive_polynomial(coefficients: Iterable[int]) -> fmpz_poly:
    polynomial = fmpz_poly(list(coefficients))

    if polynomial.is_zero():
        return polynomial

    content = abs(int(polynomial.content()))
    if content > 1:
        polynomial = fmpz_poly(
            [int(coefficient) // content for coefficient in polynomial.coeffs()]
        )

    if int(polynomial.leading_coefficient()) < 0:
        polynomial = -polynomial

    return polynomial


def _reverse_polynomial(polynomial: fmpz_poly) -> fmpz_poly:
    """Return x^d p(1/x), primitive-normalized."""
    return _primitive_polynomial(reversed(polynomial.coeffs()))


def _polynomial_key(polynomial: fmpz_poly) -> tuple[int, ...]:
    return tuple(int(coefficient) for coefficient in polynomial.coeffs())


def _polynomial_height(polynomial: fmpz_poly) -> int:
    return max(abs(int(coefficient)) for coefficient in polynomial.coeffs())


def _evaluate_polynomial(polynomial: fmpz_poly, value: acb) -> acb:
    result = acb(0)
    for coefficient in reversed(polynomial.coeffs()):
        result = result * value + int(coefficient)
    return result


def _relation_score_bits(
    polynomial: fmpz_poly,
    value: acb,
    residual: acb | None = None,
) -> arb:
    """Return a conservative normalized relation-smallness score in bits."""
    if residual is None:
        residual = _evaluate_polynomial(polynomial, value)

    residual_upper = residual.abs_upper()
    height = _polynomial_height(polynomial)
    degree = int(polynomial.degree())

    magnitude_upper = value.abs_upper()
    base = magnitude_upper if magnitude_upper > 1 else arb(1)
    normalizer = arb(height) * (base ** degree)

    if residual_upper.is_zero():
        return arb(int(ctx.prec))

    normalized_upper = residual_upper / normalizer
    if normalized_upper <= 0:
        return arb(int(ctx.prec))

    return -arb_log2_positive(normalized_upper)


def _degree_weights(degree: int, degree_cost: int) -> list[int]:
    """Return coefficient-coordinate weights ``(degree_cost + 1)**i``."""
    base = degree_cost + 1
    return [base**power for power in range(degree + 1)]


def _build_lattice(
    midpoint: acb,
    degree: int,
    scale_bits: int,
    use_complex_lattice: bool,
    degree_cost: int,
) -> tuple[fmpz_mat, list[int]]:
    """Build the integer-relation lattice.

    The diagonal coefficient block uses (degree_cost + 1)^i. This gives
    progressively higher powers a larger cost while keeping
    ``degree_cost=0`` neutral.
    """
    if degree_cost < 0:
        raise ValueError("degree_cost must be nonnegative")

    weights = _degree_weights(degree, degree_cost)
    extra_columns = 2 if use_complex_lattice else 1
    column_count = degree + 1 + extra_columns
    matrix = fmpz_mat(degree + 1, column_count)

    scale = 1 << scale_bits
    power = acb(1)

    for power_index in range(degree + 1):
        matrix[power_index, power_index] = weights[power_index]
        matrix[power_index, degree + 1] = round_arb_midpoint_to_int(
            power.real * scale
        )
        if use_complex_lattice:
            matrix[power_index, degree + 2] = round_arb_midpoint_to_int(
                power.imag * scale
            )
        power *= midpoint

    return matrix, weights


def _extract_candidates(
    reduced: fmpz_mat,
    degree: int,
    scale_bits: int,
    coefficient_weights: list[int],
    original_value: acb,
    reciprocal_used: bool,
    max_rows: int,
    max_height: int | None,
) -> list[_Candidate]:
    """Extract, normalize, deduplicate, and score several short LLL rows."""
    column_count = reduced.ncols()

    row_indices = list(range(reduced.nrows()))
    row_indices.sort(
        key=lambda row_index: sum(
            int(reduced[row_index, column_index]) ** 2
            for column_index in range(column_count)
        )
    )

    candidates: list[_Candidate] = []
    seen: set[tuple[int, ...]] = set()

    for row_index in row_indices[:max_rows]:
        weighted_coefficients = [
            int(reduced[row_index, coefficient_index])
            for coefficient_index in range(degree + 1)
        ]

        if any(
            coefficient % weight
            for coefficient, weight in zip(
                weighted_coefficients, coefficient_weights
            )
        ):
            continue

        coefficients = [
            coefficient // weight
            for coefficient, weight in zip(
                weighted_coefficients, coefficient_weights
            )
        ]

        if all(coefficient == 0 for coefficient in coefficients):
            continue

        polynomial = _primitive_polynomial(coefficients)
        if polynomial.is_zero() or polynomial.is_constant():
            continue

        # If the relation was found for y = 1/x, transform
        # q(y) = 0 into x^d q(1/x) = 0 before scoring/factoring.
        if reciprocal_used:
            polynomial = _reverse_polynomial(polynomial)

        if polynomial.is_zero() or polynomial.is_constant():
            continue

        key = _polynomial_key(polynomial)
        if key in seen:
            continue
        seen.add(key)

        height = _polynomial_height(polynomial)
        if max_height is not None and height > max_height:
            continue

        residual = _evaluate_polynomial(polynomial, original_value)
        score = _relation_score_bits(polynomial, original_value, residual)

        vector = tuple(
            int(reduced[row_index, column_index])
            for column_index in range(column_count)
        )

        candidates.append(
            _Candidate(
                polynomial=polynomial,
                residual=residual,
                score_bits=score,
                height=height,
                degree=int(polynomial.degree()),
                lattice_vector=vector,
                scale_bits=scale_bits,
            )
        )

    return candidates


def _strongest_candidates(
    candidates: list[_Candidate],
    limit: int,
) -> list[_Candidate]:
    """Select strongest candidates using Arb comparisons, never binary64."""
    ordered: list[_Candidate] = []

    for candidate in candidates:
        inserted = False
        score = candidate.score_bits.lower()

        for index, existing in enumerate(ordered):
            existing_score = existing.score_bits.lower()

            if score > existing_score:
                ordered.insert(index, candidate)
                inserted = True
                break

            if score == existing_score and (
                candidate.degree,
                candidate.height,
            ) < (
                existing.degree,
                existing.height,
            ):
                ordered.insert(index, candidate)
                inserted = True
                break

        if not inserted:
            ordered.append(candidate)

    return ordered[:limit]


def _factor_candidates(
    relation_candidates: list[_Candidate],
    value: acb,
    limit: int,
) -> list[tuple[_Candidate, fmpz_poly, acb, arb, bool, arb]]:
    """Factor only the strongest relations and identify compatible roots."""
    results = []
    seen_factors: set[tuple[int, ...]] = set()

    for relation in _strongest_candidates(relation_candidates, limit):
        content, factors = relation.polynomial.factor()
        del content

        factor_list = [factor for factor, exponent in factors]
        if not factor_list:
            factor_list = [relation.polynomial]

        for factor in factor_list:
            factor = _primitive_polynomial(factor.coeffs())
            key = _polynomial_key(factor)

            if key in seen_factors:
                continue
            seen_factors.add(key)

            factor_residual = _evaluate_polynomial(factor, value)
            factor_score = _relation_score_bits(
                factor, value, factor_residual
            )

            roots = factor.complex_roots()
            if not roots:
                continue

            overlapping = [
                root
                for root, multiplicity in roots
                if root.overlaps(value)
            ]
            certified = len(overlapping) == 1

            if certified:
                matched_root = overlapping[0]
                distance = (matched_root - value).abs_upper()
            else:
                matched_root = None
                distance = None

                for root, multiplicity in roots:
                    del multiplicity
                    root_distance = (root - value).abs_upper()
                    if distance is None or root_distance < distance:
                        matched_root = root
                        distance = root_distance

                if matched_root is None or distance is None:
                    continue

            results.append(
                (
                    relation,
                    factor,
                    matched_root,
                    distance,
                    certified,
                    factor_score,
                )
            )

    return results


def _better_factor_result(left, right) -> bool:
    """Return True if left is preferable to right."""
    if right is None:
        return True

    _, lfactor, _, ldist, lcert, lscore = left
    _, rfactor, _, rdist, rcert, rscore = right

    if lcert != rcert:
        return lcert

    ldegree = int(lfactor.degree())
    rdegree = int(rfactor.degree())
    if ldegree != rdegree:
        return ldegree < rdegree

    lheight = _polynomial_height(lfactor)
    rheight = _polynomial_height(rfactor)
    if lheight != rheight:
        return lheight < rheight

    if lscore.lower() != rscore.lower():
        return lscore.lower() > rscore.lower()

    return ldist < rdist


def _reciprocal_search_value(
    value: acb,
    enabled: bool,
) -> tuple[acb, bool]:
    """Use 1/x when the input ball is provably inside the unit circle.

    This avoids tiny powers x^i becoming numerically uninformative. The
    resulting polynomial is
    reversed before it is evaluated or returned.
    """
    if not enabled:
        return value, False

    if value.abs_upper() < 1 and value.abs_lower() > 0:
        return 1 / value, True

    return value, False


DEFAULT_MAX_DEGREE = 128


def _as_exact_fmpq(value: NumericInput) -> fmpq | None:
    """Return an exact rational representation when one is available."""
    if isinstance(value, fmpq):
        return value
    if isinstance(value, fmpz):
        return fmpq(value)
    if isinstance(value, Fraction):
        return fmpq(value.numerator, value.denominator)
    if isinstance(value, int):
        return fmpq(value)
    return None


def _exact_rational_result(value: fmpq) -> AlgRecognizeResult:
    """Return the exact linear relation for a rational input p/q."""
    numerator = int(value.numerator)
    denominator = int(value.denominator)
    polynomial = _primitive_polynomial([-numerator, denominator])
    root = acb(value)

    return AlgRecognizeResult(
        polynomial=polynomial,
        relation_polynomial=polynomial,
        matched_root=root,
        root_distance_upper=arb(0),
        residual=acb(0),
        relation_score_bits=arb(int(ctx.prec)),
        acceptance_threshold_bits=0,
        input_accuracy_bits=None,
        input_is_exact=True,
        degree_searched=1,
        polynomial_height=_polynomial_height(polynomial),
        scale_bits=0,
        magnitude_exponent_bits=binary_magnitude_exponent(root),
        lattice_vector=(),
        certified=True,
        confidence="exact",
        reciprocal_normalization_used=False,
    )


def algrecognize(
    value: NumericInput,
    max_degree: int,
    *,
    max_height: int | None = None,
    min_relation_bits: int | None = None,
    mode: InputMode = "auto",
    lattice_scale_bits: int | None = None,
    degree_cost: int = 0,
    reciprocal_normalization: bool = True,
    candidates_per_degree: int = 8,
    factor_candidates_per_degree: int = 4,
    minimum_input_accuracy_bits: int = 24,
    allow_large_degree: bool = False,
) -> AlgRecognizeResult:
    """Recognize a likely algebraic number from a numerical approximation.

    The search is based on integer-relation lattices reduced by FLINT's LLL
    implementation, followed by FLINT integer-polynomial factorization and
    certified complex root isolation.

    Exact integer and rational inputs are handled deterministically without
    LLL. Approximate inputs use integer-relation lattices reduced by FLINT.

    By default, degree searches above ``DEFAULT_MAX_DEGREE`` are rejected
    because LLL cost can grow rapidly. Advanced users may opt in with
    ``allow_large_degree=True``.

    See the package README for the mathematical model, confidence semantics,
    parameter guidance, and the distinction between numerical recognition and
    proof of algebraicity.
    """
    if max_degree < 1:
        raise ValueError("max_degree must be at least 1")
    if max_degree > DEFAULT_MAX_DEGREE and not allow_large_degree:
        raise SearchLimitError(
            f"max_degree={max_degree} exceeds the default safety limit "
            f"of {DEFAULT_MAX_DEGREE}; pass allow_large_degree=True only "
            "after considering the potentially high LLL cost"
        )

    exact_value = _as_exact_fmpq(value)
    if exact_value is not None:
        return _exact_rational_result(exact_value)
    if max_height is not None and max_height < 1:
        raise ValueError("max_height must be positive")
    if degree_cost < 0:
        raise ValueError("degree_cost must be nonnegative")
    if candidates_per_degree < 1:
        raise ValueError("candidates_per_degree must be positive")
    if factor_candidates_per_degree < 1:
        raise ValueError("factor_candidates_per_degree must be positive")

    original_precision = int(ctx.prec)

    z, use_complex_lattice, source_cap = as_acb_and_mode(value, mode)
    accuracy_bits = usable_accuracy_bits(z, source_cap)

    if accuracy_bits < minimum_input_accuracy_bits:
        raise InsufficientAccuracyError(
            f"input has only about {accuracy_bits} trustworthy bits; "
            f"at least {minimum_input_accuracy_bits} are required"
        )

    if min_relation_bits is None:
        threshold = max(24, (2 * accuracy_bits) // 3)
    else:
        if min_relation_bits < 1:
            raise ValueError("min_relation_bits must be positive")
        threshold = min_relation_bits

    search_value, reciprocal_used = _reciprocal_search_value(
        z, reciprocal_normalization
    )

    try:
        # Search from low degree upward. The first degree with a convincing
        # irreducible relation wins, which naturally prefers simpler algebraic
        # explanations and avoids high-degree multiples.
        for search_degree in range(1, max_degree + 1):
            ctx.prec = working_precision_bits(
                accuracy_bits, search_degree, search_value
            )

            magnitude_exponent_bits = binary_magnitude_exponent(search_value)
            scale_bits = choose_scale_bits(
                accuracy_bits,
                search_degree,
                magnitude_exponent_bits,
                lattice_scale_bits,
            )

            lattice, coefficient_weights = _build_lattice(
                midpoint=search_value.mid(),
                degree=search_degree,
                scale_bits=scale_bits,
                use_complex_lattice=use_complex_lattice,
                degree_cost=degree_cost,
            )
            reduced = lattice.lll()

            # Accuracy-dependent default height guard. Large-height algebraic
            # numbers remain accessible by setting max_height explicitly.
            if max_height is None:
                default_height_bits = max(
                    8,
                    accuracy_bits // (2 * (search_degree + 1)),
                )
                effective_max_height = 1 << default_height_bits
            else:
                effective_max_height = max_height

            candidates = _extract_candidates(
                reduced=reduced,
                degree=search_degree,
                scale_bits=scale_bits,
                coefficient_weights=coefficient_weights,
                original_value=z,
                reciprocal_used=reciprocal_used,
                max_rows=min(candidates_per_degree, reduced.nrows()),
                max_height=effective_max_height,
            )

            convincing = [
                candidate
                for candidate in candidates
                if candidate.score_bits.lower() >= threshold
            ]
            if not convincing:
                continue

            factored = _factor_candidates(
                convincing,
                z,
                factor_candidates_per_degree,
            )

            factored = [
                item
                for item in factored
                if item[5].lower() >= threshold
            ]

            best = None
            for item in factored:
                if _better_factor_result(item, best):
                    best = item

            if best is None:
                continue

            relation, factor, root, distance, certified, factor_score = best
            factor_residual = _evaluate_polynomial(factor, z)

            return AlgRecognizeResult(
                polynomial=factor,
                relation_polynomial=relation.polynomial,
                matched_root=root,
                root_distance_upper=distance,
                residual=factor_residual,
                relation_score_bits=factor_score.lower(),
                acceptance_threshold_bits=threshold,
                input_accuracy_bits=accuracy_bits,
                input_is_exact=False,
                degree_searched=search_degree,
                polynomial_height=_polynomial_height(factor),
                scale_bits=scale_bits,
                magnitude_exponent_bits=magnitude_exponent_bits,
                lattice_vector=relation.lattice_vector,
                certified=certified,
                confidence="certified" if certified else "high_confidence",
                reciprocal_normalization_used=reciprocal_used,
            )

    finally:
        ctx.prec = original_precision

    raise NoRelationFound(
        "no algebraic relation passed the normalized residual threshold "
        f"({threshold} bits) through degree {max_degree}"
    )
